"""Primary-source decisions for thermal circuits and SNAPCAR origami demonstrations."""
import json,re
import ledger as L
from review_batch_0001 import evidence

def main():
 before=L.counts();batch='AUTHOR0010';rid='author-priority-william-shih';base=L.ROOT/'assets/research-20261105';archives={a['ordinal']:a for a in json.loads((L.HERE/'shih_source_archive_inventory.json').read_text())}
 h='10.1093/nar/gkz844';k='10.1002/anie.201710469';pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 def ev(n,file,locator):return evidence(base/f'shih-extracted/{n}'/file,archives[n]['archive']['url'],locator)
 hm=ev(26,'HahnJ_nar_2019.pdf','pp10968–10975 abstract/methods/results/discussion; mainFigs1,4–6 captions and reference7; first-online date onp10968')
 hs=ev(26,'HahnJ_nar_2019_SI.pdf','SI1.1/Table1 sequence descriptions for incumbent/substrate/AC strands and gate components; SI1.2 data processing')
 km=ev(32,'KriegE_acie_2018.pdf','pp714–718; Fig4/results p716–717, references2/8/29/30, acknowledgments and first-online dates p718')
 ks=ev(32,'KriegE_acie_2018_SI.pdf','Folding of DNA Origami printedS11–12; FigsS18–20 visually inspected PDFpp23–24/printedS22–23; TableS2 primers; templates and SIreferences')
 hn='Thermal associative strand displacement uses free incumbent/substrate, associative-complex strands and threshold/input/output gates in solution. Methods and SI sequence table specify short DNA components and fluorophore/quencher reporters; results demonstrate temperature cycling and OR/AND concentration-threshold logic. No DNA-origami object is presented, modified or reused. Mainref7 cites an origami SNP chip as background and is retained as a discovery lead. Exclusion is based on inspected experimental architecture, not the word devices or absence of origami in title.'
 p=pubs.get(h,dict(registry_key=h,registry_id=None,doi=h,canonical_work_id='work:'+h,canonical_work_status='provisional_unreconciled',version_links=[],legacy_record={},evidence=[]))
 for e in [hm,hs]:
  if e not in p['evidence']:p['evidence'].append(e)
 p.update(title='Thermal cycling of DNA devices via associative strand displacement',authors=['Jaeseung Hahn','William M. Shih'],publication_type=['journal_article'],review_stage='fulltext_reviewed',relevance='not_origami',design_contributions=[],catalog_eligibility='excluded',access='main_and_SI_available',rationale=hn,reviewer='Codex main/SI experimental-scope inspection',run_id=rid,date=L.DATE,date_evidence={'date':'2019-10-04','source':hm,'primary_verified':True,'meaning':'Published online date printed on mainp10968'},temporal_scope='pre2020_verified',unresolved_questions=['Follow relevant cited origami work and reconcile all retained reference identities.'])
 L.upsert('publication_reviews',p,'Record evidence-based exclusion while retaining origami citation leads')
 kn='SNAPCAR-produced scaffolds experimentally fold three origami objects: barrel fromss3315, rectangle and6-helix bundle fromss7301. Main reported dimensions are barrel diameter30.7±1.0nm, rectangle length90.1±3.5nm and6HB length405±11nm. SI explicitly attributes barrel to Ponnuswamy2017, rectangle adaptation to Rothemund2006 and Jungmann2016, and6HB to Mathieu2005/Douglas2007. SI states multilayer designs follow honeycomb method; single-layer follows Rothemund. FigsS18–20 show flattened routed strands, with red deletion marks in barrel/rectangle and three displayed segments for6HB; no numbered cross-sectional layout or native design files in acquired archive. TableS2 is eight PCR primers, not a complete staple list. p7308 template produces3315/7301nt products. Acknowledgments credit John Min for barrel design ahead of publication; exact upstream variant and relationship to MeRPy2019 require comparison.'
 unresolved=['Acquire/verify complete staple lists and native routing for all three objects; sequence-to-route and catalog eligibility remain unverified.','Resolve exact barrel relationship to Ponnuswamy DN labels and MeRPy2019 p3315/miniscaffold; do not merge by dimensions alone.','Reconcile rectangle and6HB parent variants; retain all backward/forward citation routes.','Reconcile accepted manuscript online2017-12-05, VOR2017-12-18 and2018 issue as versions/date meanings; German-edition DOI10.1002/ange.201710469 remains a separate pending lead.']
 p=pubs[k]
 for e in [km,ks]:
  if e not in p['evidence']:p['evidence'].append(e)
 p.update(title='Selective Nascent Polymer Catch-and-Release Enables Scalable Isolation of Multi-Kilobase Single-Stranded DNA',authors=['Elisha Krieg','William M. Shih'],publication_type=['journal_article'],review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['reused_design','modified_design'],catalog_eligibility='unresolved',access='main_and_SI_available_staple_completeness_unverified',rationale=kn,reviewer='Codex main/SI protocols, diagrams and sequence-section review',run_id=rid,date=L.DATE,date_evidence={'date':'2017-12-05','source':km,'primary_verified':True,'meaning':'Accepted manuscript online; VOR online2017-12-18; issue2018'},temporal_scope='pre2020_verified',unresolved_questions=unresolved)
 L.upsert('publication_reviews',p,'Record three reuse demonstrations and earliest public date meaning')
 did='RDE0047';old=next((d for d in L.read('design_evidence') if d['design_id']==did),None)
 if old:assert k in old['publication_keys']
 L.upsert('design_evidence',dict(design_id=did,publication_keys=[k],named_objects=['SNAPCAR barrel ss3315','SNAPCAR rectangle ss7301','SNAPCAR6HB ss7301'],identity_status='Three-object source group with explicit reuse/adaptation; exact upstream variants pending',lattice_decision='SI reports honeycomb method for multilayer objects and Rothemund method for single-layer; exact per-object native routing/source verification incomplete',catalog_eligibility='unresolved',core_variant_composition=kn,relationships=[{'relation':'reuses_design_from','target':'10.1038/ncomms15654','scope':'Barrel mainref29 andSIref6; exact variant unresolved'}],variant_links=[],source_completeness='not_verified',evidence=[km,ks],source_files=[archives[32]['archive'],km,ks],outstanding_checks=unresolved,review_stage='source_reviewed',review_run=batch,run_id=rid,date=L.DATE,legacy_record={}), 'Retain three experimental objects without certifying completeness')
 L.upsert('discovery_edges',dict(edge_id='krieg2018:barrel-parent',source_key=k,target_key='10.1038/ncomms15654',relation='reuses_design_from',evidence_url=km['url'],local_file=km['local_file'],sha256=km['sha256'],locator='mainref29 and SIref6',reconciliation_state='explicit_parent_attribution; exact_variant_pending',run_id=rid,date=L.DATE),'Record attributed barrel parent')
 L.upsert('discovery_edges',dict(edge_id='krieg2018:german-edition',source_key=k,target_key='10.1002/ange.201710469',relation='parallel_edition_lead',evidence_url=km['url'],local_file=km['local_file'],sha256=km['sha256'],locator='mainp714 German Edition DOI',reconciliation_state='pending_edition_version_reconciliation',run_id=rid,date=L.DATE),'Preserve explicitly listed German edition without merging')
 reference_audit=[]
 for key,prefix,count in [(h,'hahn2019',24),(k,'krieg2018',30)]:
  path=base/(prefix+'-crossref.json');m=json.loads(path.read_text())['message'];refs=m['reference'];assert len(refs)==m['reference-count']==count
  e=evidence(path,'https://api.crossref.org/works/'+key,'Publisher-deposited reference list; all entries retained. Counts agree with final numbered reference in mainPDF.')
  for n,r in enumerate(refs,1):
   doi=r.get('DOI','').lower();target=doi if doi in pubs else (doi or 'citation:'+prefix+':'+str(n))
   L.upsert('discovery_edges',dict(edge_id=prefix+':reference:'+str(n),source_key=key,target_key=target,relation='cites',evidence_url=e['url'],local_file=e['local_file'],sha256=e['sha256'],locator='reference array index'+str(n-1),citation=r,reconciliation_state='explicit_doi_registry_match; source_scope_pending' if doi in pubs else 'pending_identity_reconciliation',run_id=rid,date=L.DATE),'Retain complete deposited references, no relevance cap')
  reference_audit.append({'publication':key,'count':count,'evidence':e})
 si_text=(base/'shih-extracted/32/KriegE_acie_2018_SI.txt').read_text();part=si_text.rsplit('References',1)[1];matches=list(re.finditer(r'^\[(\d+)\]\s+',part,re.M));assert [int(m[1]) for m in matches]==list(range(1,11))
 for i,m in enumerate(matches):
  citation=' '.join(part[m.end():matches[i+1].start() if i+1<len(matches) else len(part)].split()).removesuffix('S-36').strip()
  L.upsert('discovery_edges',dict(edge_id='krieg2018:SIreference:'+m[1],source_key=k,target_key='citation:krieg2018:SI:'+m[1],relation='cites',evidence_url=ks['url'],local_file=ks['local_file'],sha256=ks['sha256'],locator='SIreference'+m[1]+' printedS36',citation=citation,reconciliation_state='pending_identity_reconciliation',run_id=rid,date=L.DATE),'Retain all ten supplement references separately from main list')
 invpath=L.HERE/'shih_bibliography_inventory.json';inv=json.loads(invpath.read_text())
 for row in inv['entries']:
  if row['ordinal'] in [26,32]:row.update(target_key=h if row['ordinal']==26 else k,identity_status='primary_title_authors_doi_date_verified',review_status='non_origami_scope_verified' if row['ordinal']==26 else 'three_origami_objects_source_reviewed; completeness_pending')
 L.atomic(invpath,json.dumps(inv,indent=2)+'\n')
 for ordinal,key in [(26,h),(32,k)]:
  edge=next(e for e in L.read('discovery_edges') if e['edge_id']==rid+':lab:'+str(ordinal))
  edge.update(target_key=key,reconciliation_state='primary_identity_and_scope_reviewed; source_completeness_pending' if ordinal==32 else 'primary_identity_and_non_origami_scope_verified')
  L.upsert('discovery_edges',edge,'Resolve author bibliography identity against inspected primary source')
 L.upsert('batches',dict(batch_id=batch,date=L.DATE,status='completed',input_keys=[h,k],selection='Two previously acquired Shih archives, including low-keyword thermal-device record',completed_actions=['Excluded thermal-circuit study after main/SI architecture inspection; retained its origami-chip reference.','Reviewed SNAPCAR three origami demonstrations, protocols, primers and all three strand diagrams; recorded2017 online dates versus2018 issue.','Retained54 main deposited references plus10 SI references and German-edition lead.'],before_counts=before,after_counts=L.counts(),unresolved_keys=[k],exclusion_audit={'sample':[{'key':h,'evidence':[hm,hs],'reason':hn}],'denominator':1,'meaning':'One new publication exclusion checked against methods/results and SI components'},reference_audit=reference_audit,validation=[L.validate()],next_queue=unresolved+['Review P0103 DOI10.1002/smll.201000908 origami SNP chip cited by Hahn.','Continue requested author histories and low-keyword rotation; recover Tellechea source.']), 'Save primary source review and complete bounded citation enumeration')
 print(L.validate())
if __name__=='__main__':main()
